'use strict';
/* IPC HMAC secret is never generated by a service at startup.
 * Load only an existing, root-bound, owner-only file on the local trial.
 */
const fs=require('node:fs'),path=require('node:path');
const {active}=require('./auth21_service_boundary');
function loadTrialSecret({env,root}={}){
 if(!active(env))throw Error('AUTH21_IPC_TRIAL_REQUIRED');
 const allowed=require('../Backup/auth21_core_local_trial_wiring').preflightEnv(env);
 if(root!==allowed.root)throw Error('AUTH21_IPC_ROOT_MISMATCH');
 const name=path.join(root,'userdata','Security','auth21_ipc.key');
 const st=fs.lstatSync(name);
 if(!st.isFile()||st.isSymbolicLink()||(st.mode&0o077)!==0||
    fs.realpathSync(name)!==name||st.size!==32)throw Error('AUTH21_IPC_KEY_UNSAFE');
 const key=fs.readFileSync(name);
 if(key.length!==32)throw Error('AUTH21_IPC_KEY_UNSAFE');
 return key;
}
module.exports={loadTrialSecret};
